  (* XILINX_LEGACY_PRIM = "SRL16" *) 
  (* XILINX_TRANSFORM_PINMAP = "VCC:CE" *) 
  (* srl_name = "inst/u_ddr4_mem_intfci_12/\u_ddr_cal_riu/mcs0 /inst/rst_0/U0/\EXT_LPF/POR_SRL_I " *) 
